from dataclasses import dataclass
from typing import List, Dict, Tuple, Set
import heapq

GPU_MEM_SIZE = 80  # GB

@dataclass
class Model:
    model_name: str
    model_size: int   # GB
    req_rate: int     # requests per second
    slo: int          # service level objective (latency target)
    cur_gpu_id: int   # current GPU assignment (can be ignored)

def compute_model_placement(gpu_num: int, models: List[Model]) -> Dict[int, List[Model]]:
    if not models:
        return {g: [] for g in range(gpu_num)}

    n = len(models)
    weights = [m.req_rate / m.slo for m in models]
    sizes = [m.model_size for m in models]

    # Binary search on maximum KVPR threshold
    low, high = 0.0, 100.0
    best_placement = None
    best_max_kvpr = float('inf')

    for _ in range(60):
        mid = (low + high) / 2.0
        placement: Dict[int, List[int]] = {g: [] for g in range(gpu_num)}
        used_memory = [0] * gpu_num
        used_weights = [0.0] * gpu_num
        feasible = True

        # Sort models by (weight / size) descending for greedy packing
        order = sorted(range(n), key=lambda i: weights[i] / max(sizes[i], 1e-9), reverse=True)

        for i in order:
            best_gpu = -1
            best_available = -1
            for g in range(gpu_num):
                free_mem = GPU_MEM_SIZE - used_memory[g]
                if sizes[i] > free_mem:
                    continue
                new_used_mem = used_memory[g] + sizes[i]
                new_used_w = used_weights[g] + weights[i]
                if new_used_mem == GPU_MEM_SIZE:
                    continue
                kvpr_g = new_used_w / (GPU_MEM_SIZE - new_used_mem)
                if kvpr_g <= mid:
                    if best_gpu == -1 or new_used_mem > best_available:
                        best_gpu = g
                        best_available = new_used_mem

            if best_gpu == -1:
                feasible = False
                break
            placement[best_gpu].append(i)
            used_memory[best_gpu] += sizes[i]
            used_weights[best_gpu] += weights[i]

        if feasible:
            max_kvpr = max(used_weights[g] / (GPU_MEM_SIZE - used_memory[g]) if used_memory[g] < GPU_MEM_SIZE else 0 for g in range(gpu_num))
            if max_kvpr < best_max_kvpr:
                best_max_kvpr = max_kvpr
                best_placement = {g: placement[g][:] for g in range(gpu_num)}
            high = mid
        else:
            low = mid

    # Final cleanup: map indices back to models
    result: Dict[int, List[Model]] = {g: [] for g in range(gpu_num)}
    for g in range(gpu_num):
        result[g] = [models[i] for i in best_placement[g]]

    # Local search with tabu list to avoid cycling
    tabu_list = set()
    tabu_size = 10
    improvements = []

    # Initial improvement candidates
    for g in range(gpu_num):
        for i_idx in best_placement[g]:
            for g2 in range(gpu_num):
                if g == g2:
                    continue
                for j_idx in best_placement[g2]:
                    if sizes[i_idx] + used_memory[g2] > GPU_MEM_SIZE or sizes[j_idx] + used_memory[g] > GPU_MEM_SIZE:
                        continue
                    new_w_g = used_weights[g] - weights[i_idx] + weights[j_idx]
                    new_m_g = used_memory[g] - sizes[i_idx] + sizes[j_idx]
                    new_kv_g = new_w_g / (GPU_MEM_SIZE - new_m_g)
                    new_w_g2 = used_weights[g2] - weights[j_idx] + weights[i_idx]
                    new_m_g2 = used_memory[g2] - sizes[j_idx] + sizes[i_idx]
                    new_kv_g2 = new_w_g2 / (GPU_MEM_SIZE - new_m_g2)
                    old_max = max(used_weights[g] / (GPU_MEM_SIZE - used_memory[g]), used_weights[g2] / (GPU_MEM_SIZE - used_memory[g2]))
                    new_max = max(new_kv_g, new_kv_g2)
                    if new_max < old_max - 1e-9:
                        state_key = (min(i_idx, j_idx), max(i_idx, j_idx), g, g2)
                        if state_key not in tabu_list:
                            heapq.heappush(improvements, (new_max - old_max, g, i_idx, g2, j_idx))

    # Apply top improvements with tabu filtering
    while improvements:
        diff, g1, i, g2, j = heapq.heappop(improvements)
        state_key = (min(i, j), max(i, j), g1, g2)
        if state_key in tabu_list:
            continue
        tabu_list.add(state_key)
        if len(tabu_list) > tabu_size:
            tabu_list.pop()  # Remove oldest

        # Perform swap
        best_placement[g1].remove(i)
        best_placement[g2].remove(j)
        best_placement[g1].append(j)
        best_placement[g2].append(i)
        used_memory[g1] = sum(sizes[idx] for idx in best_placement[g1])
        used_memory[g2] = sum(sizes[idx] for idx in best_placement[g2])
        used_weights[g1] = sum(weights[idx] for idx in best_placement[g1])
        used_weights[g2] = sum(weights[idx] for idx in best_placement[g2])

        # Re-scan for new improvements
        for g in range(gpu_num):
            for idx1 in best_placement[g]:
                for g2 in range(gpu_num):
                    if g == g2:
                        continue
                    for idx2 in best_placement[g2]:
                        if sizes[idx1] + used_memory[g2] > GPU_MEM_SIZE or sizes[idx2] + used_memory[g] > GPU_MEM_SIZE:
                            continue
                        new_w_g1 = used_weights[g] - weights[idx1] + weights[idx2]
                        new_m_g1 = used_memory[g] - sizes[idx1] + sizes[idx2]
                        new_kv_g1 = new_w_g1 / (GPU_MEM_SIZE - new_m_g1)
                        new_w_g2 = used_weights[g2] - weights[idx2] + weights[idx1]
                        new_m_g2 = used_memory[g2] - sizes[idx2] + sizes[idx1]
                        new_kv_g2 = new_w_g2 / (GPU_MEM_SIZE - new_m_g2)
                        old_max = max(used_weights[g] / (GPU_MEM_SIZE - used_memory[g]), used_weights[g2] / (GPU_MEM_SIZE - used_memory[g2]))
                        new_max = max(new_kv_g1, new_kv_g2)
                        if new_max < old_max - 1e-9:
                            state_key = (min(idx1, idx2), max(idx1, idx2), g, g2)
                            if state_key not in tabu_list:
                                heapq.heappush(improvements, (new_max - old_max, g, idx1, g2, idx2))

    # Final mapping
    result = {g: [models[i] for i in best_placement[g]] for g in range(gpu_num)}
    return result

from dataclasses import dataclass
from typing import List, Dict, Tuple, Set, Optional
import math
import random

GPU_MEM_SIZE = 80  # GB

@dataclass
class Model:
    model_name: str
    model_size: int   # GB
    req_rate: int     # requests per second
    slo: int          # service level objective (latency target)
    cur_gpu_id: int   # current GPU assignment (can be ignored)

def compute_model_placement(gpu_num: int, models: list[Model]) -> dict[int, list[Model]]:
    M = GPU_MEM_SIZE
    n = len(models)
    if n == 0:
        return {g: [] for g in range(gpu_num)}

    sizes = [m.model_size for m in models]
    weights = [m.req_rate / m.slo for m in models]

    for i, s in enumerate(sizes):
        if s > M:
            raise ValueError(f"Model {models[i].model_name} size {s} exceeds GPU capacity {M}.")

    total_size = sum(sizes)
    total_w = sum(weights)

    denom = gpu_num * M - total_size
    global_lb = total_w / denom if denom > 1e-12 else float('inf')
    per_model_lb = max((weights[i] / max(M - sizes[i], 1e-12)) for i in range(n))
    tau_low = max(global_lb, per_model_lb, 0.0)

    def model_key(i: int) -> Tuple[float, int, float, str]:
        return (weights[i] / max(M - sizes[i], 1e-12), -sizes[i], weights[i], models[i].model_name)
    order = sorted(range(n), key=model_key, reverse=True)

    def greedy_upper() -> Tuple[float, Dict[int, List[int]]]:
        used_s = [0] * gpu_num
        used_w = [0.0] * gpu_num
        placement_idx: Dict[int, List[int]] = {g: [] for g in range(gpu_num)}
        for i in order:
            best_g = None
            best_max = float('inf')
            candidates = [g for g in range(gpu_num) if used_s[g] + sizes[i] < M - 1e-12]
            for g in candidates:
                s_after = used_s[g] + sizes[i]
                w_after = used_w[g] + weights[i]
                denom_g = M - s_after
                kvpr_g = w_after / denom_g if denom_g > 1e-12 else float('inf')
                worst = kvpr_g
                for h in range(gpu_num):
                    if h == g:
                        continue
                    dh = M - used_s[h]
                    if dh <= 1e-12:
                        if used_w[h] > 0:
                            worst = float('inf')
                            break
                        continue
                    worst = max(worst, used_w[h] / dh)
                if worst < best_max:
                    best_max = worst
                    best_g = g
            if best_g is None:
                best_g = max(range(gpu_num), key=lambda g: used_s[g])
                if used_s[best_g] + sizes[i] >= M - 1e-12:
                    best_g = min(range(gpu_num), key=lambda g: used_w[g] / max(M - used_s[g], 1e-12))
            used_s[best_g] += sizes[i]
            used_w[best_g] += weights[i]
            placement_idx[best_g].append(i)
        max_k = 0.0
        for g in range(gpu_num):
            denom_g = M - used_s[g]
            if denom_g > 1e-12:
                max_k = max(max_k, used_w[g] / denom_g)
            elif used_w[g] > 0:
                max_k = float('inf')
        return max_k, placement_idx

    def feasible_pack(tau: float) -> Tuple[bool, Dict[int, List[int]]]:
        used_s = [0] * gpu_num
        used_w = [0.0] * gpu_num
        placement: Dict[int, List[int]] = {g: [] for g in range(gpu_num)}
        assigned = [-1] * n

        def gpu_order_for_item(i: int) -> List[int]:
            cands = []
            for g in range(gpu_num):
                s_after = used_s[g] + sizes[i]
                if s_after >= M - 1e-12:
                    continue
                w_after = used_w[g] + weights[i]
                if w_after <= tau * (M - s_after) + 1e-12:
                    denom_g = M - s_after
                    kv_est = w_after / denom_g if denom_g > 1e-12 else float('inf')
                    score = kv_est + 1e-6 * (M - s_after)
                    cands.append((score, g))
            cands.sort(key=lambda x: (x[0], x[1]))
            picked = [g for (_, g) in cands]
            picked += [g for g in range(gpu_num) if g not in picked]
            return picked

        def place_with_relocation(i: int, visiting: Set[int], banned: Dict[int, Set[int]]) -> bool:
            if i in visiting:
                return False
            visiting.add(i)

            for g in gpu_order_for_item(i):
                if g in banned.get(i, set()):
                    continue
                s_after = used_s[g] + sizes[i]
                if s_after >= M - 1e-12:
                    continue
                w_after = used_w[g] + weights[i]
                if w_after <= tau * (M - s_after) + 1e-12:
                    placement[g].append(i)
                    used_s[g] += sizes[i]
                    used_w[g] += weights[i]
                    assigned[i] = g
                    visiting.remove(i)
                    return True

            gpu_candidates = []
            for g in range(gpu_num):
                if g in banned.get(i, set()):
                    continue
                s_after = used_s[g] + sizes[i]
                w_after = used_w[g] + weights[i]
                mem_def = max(0.0, s_after - (M - 1e-12))
                lin_def = max(0.0, w_after - (tau * (M - s_after)))
                deficit = mem_def + lin_def
                gpu_candidates.append((deficit, g))
            gpu_candidates.sort(key=lambda x: (x[0], x[1]))

            for _, g in gpu_candidates:
                movable_js = []
                for j in placement[g]:
                    if j in visiting:
                        continue
                    s2 = used_s[g] - sizes[j] + sizes[i]
                    w2 = used_w[g] - weights[j] + weights[i]
                    if s2 < M - 1e-12 and w2 <= tau * (M - s2) + 1e-12:
                        alt = 0
                        for h in range(gpu_num):
                            if h == g:
                                continue
                            if h in banned.get(j, set()):
                                continue
                            ss = used_s[h] + sizes[j]
                            if ss >= M - 1e-12:
                                continue
                            ww = used_w[h] + weights[j]
                            if ww <= tau * (M - ss) + 1e-12:
                                alt += 1
                        movable_js.append((-(alt), j))
                movable_js.sort()
                for _, j in movable_js:
                    placement[g].remove(j)
                    used_s[g] -= sizes[j]
                    used_w[g] -= weights[j]
                    assigned[j] = -1
                    banned.setdefault(j, set()).add(g)
                    if place_with_relocation(j, visiting, banned):
                        s2 = used_s[g] + sizes[i]
                        w2 = used_w[g] + weights[i]
                        if s2 < M - 1e-12 and w2 <= tau * (M - s2) + 1e-12:
                            placement[g].append(i)
                            used_s[g] += sizes[i]
                            used_w[g] += weights[i]
                            assigned[i] = g
                            visiting.remove(i)
                            return True
                    banned[j].discard(g)
                    placement[g].append(j)
                    used_s[g] += sizes[j]
                    used_w[g] += weights[j]
                    assigned[j] = g
            visiting.remove(i)
            return False

        for i in order:
            if not place_with_relocation(i, set(), {}):
                return False, {}
        return True, placement

    ub_val, ub_assign_idx = greedy_upper()
    tau_high = ub_val if math.isfinite(ub_val) and ub_val > tau_low else max(tau_low * 2.0, tau_low + 1.0)

    best_tau = float('inf')
    best_assign_idx: Dict[int, List[int]] = {}

    if math.isfinite(ub_val):
        ok, pack = feasible_pack(ub_val)
        if ok:
            best_tau = ub_val
            best_assign_idx = pack

    big_tau = max(tau_high * 8.0, tau_low + 100.0)
    ok_big, pack_big = feasible_pack(big_tau)
    if ok_big:
        tau_high = min(tau_high, big_tau)
        if big_tau < best_tau:
            best_tau = big_tau
            best_assign_idx = pack_big

    if not best_assign_idx:
        ok, pack = feasible_pack(tau_high)
        if ok:
            best_tau = tau_high
            best_assign_idx = pack

    if not best_assign_idx:
        best_assign_idx = ub_assign_idx

    left = tau_low
    right = max(tau_high, left + 1.0)
    ok_r, pack_r = feasible_pack(right)
    if ok_r and right < best_tau:
        best_tau = right
        best_assign_idx = pack_r

    for _ in range(24):
        mid = 0.5 * (left + right)
        if not math.isfinite(mid):
            break
        ok, pack = feasible_pack(mid)
        if ok:
            right = mid
            if mid < best_tau:
                best_tau = mid
                best_assign_idx = pack
        else:
            left = mid
        if right - left <= max(1e-6, 1e-6 * right):
            break

    if not best_assign_idx:
        best_assign_idx = ub_assign_idx

    gpu_to_idx: List[List[int]] = [[] for _ in range(gpu_num)]
    for g, lst in best_assign_idx.items():
        for i in lst:
            gpu_to_idx[g].append(i)

    assigned_gpu = [-1] * n
    for g in range(gpu_num):
        for i in gpu_to_idx[g]:
            assigned_gpu[i] = g

    for i in range(n):
        if assigned_gpu[i] == -1:
            rems = [M - sum(sizes[k] for k in gpu_to_idx[g]) for g in range(gpu_num)]
            g = max(range(gpu_num), key=lambda gg: (rems[gg] - sizes[i], rems[gg]))
            gpu_to_idx[g].append(i)
            assigned_gpu[i] = g

    rem_mem = [M - sum(sizes[i] for i in gpu_to_idx[g]) for g in range(gpu_num)]
    weight_sum = [sum(weights[i] for i in gpu_to_idx[g]) for g in range(gpu_num)]

    def kvpr_of(g: int) -> float:
        denom_g = rem_mem[g]
        if denom_g <= 1e-12:
            return float('inf') if weight_sum[g] > 0 else 0.0
        return weight_sum[g] / denom_g

    def current_max_kvpr() -> Tuple[float, int]:
        vals = [kvpr_of(g) for g in range(gpu_num)]
        mx = max(vals)
        return mx, int(max(range(gpu_num), key=lambda x: vals[x]))

    best_max, _ = current_max_kvpr()
    best_state = [list(lst) for lst in gpu_to_idx]
    best_rem = list(rem_mem)
    best_wsum = list(weight_sum)

    def apply_move_single(i: int, g_from: int, g_to: int):
        gpu_to_idx[g_from].remove(i)
        gpu_to_idx[g_to].append(i)
        assigned_gpu[i] = g_to
        rem_mem[g_from] += sizes[i]
        rem_mem[g_to] -= sizes[i]
        weight_sum[g_from] -= weights[i]
        weight_sum[g_to] += weights[i]

    def apply_swap(i: int, j: int, g1: int, g2: int):
        gpu_to_idx[g1].remove(i)
        gpu_to_idx[g2].remove(j)
        gpu_to_idx[g1].append(j)
        gpu_to_idx[g2].append(i)
        assigned_gpu[i] = g2
        assigned_gpu[j] = g1
        rem_mem[g1] += sizes[i] - sizes[j]
        rem_mem[g2] += sizes[j] - sizes[i]
        weight_sum[g1] += weights[j] - weights[i]
        weight_sum[g2] += weights[i] - weights[j]

    max_hill_iters = 2000
    improved = True
    iters = 0
    while improved and iters < max_hill_iters:
        iters += 1
        improved = False
        cur_max, worst_g = current_max_kvpr()
        best_new_max = cur_max
        best_op = None

        for i in list(gpu_to_idx[worst_g]):
            si, wi = sizes[i], weights[i]
            for g in range(gpu_num):
                if g == worst_g:
                    continue
                if rem_mem[g] >= si - 1e-12:
                    new_rem_worst = rem_mem[worst_g] + si
                    new_w_worst = weight_sum[worst_g] - wi
                    new_rem_g = rem_mem[g] - si
                    new_w_g = weight_sum[g] + wi
                    new_max = 0.0
                    for h in range(gpu_num):
                        if h == worst_g:
                            denom = new_rem_worst
                            kv = (new_w_worst / denom) if denom > 1e-12 else (0.0 if new_w_worst <= 1e-12 else float('inf'))
                        elif h == g:
                            denom = new_rem_g
                            kv = (new_w_g / denom) if denom > 1e-12 else (0.0 if new_w_g <= 1e-12 else float('inf'))
                        else:
                            denom = rem_mem[h]
                            kv = (weight_sum[h] / denom) if denom > 1e-12 else (0.0 if weight_sum[h] <= 1e-12 else float('inf'))
                        if kv > new_max:
                            new_max = kv
                    if new_max + 1e-9 < best_new_max:
                        best_new_max = new_max
                        best_op = ('move', i, worst_g, g)

        for g in range(gpu_num):
            if g == worst_g:
                continue
            for i in list(gpu_to_idx[worst_g]):
                si, wi = sizes[i], weights[i]
                for j in list(gpu_to_idx[g]):
                    sj, wj = sizes[j], weights[j]
                    if rem_mem[worst_g] + si - sj < -1e-12 or rem_mem[g] + sj - si < -1e-12:
                        continue
                    new_rem_worst = rem_mem[worst_g] + si - sj
                    new_w_worst = weight_sum[worst_g] - wi + wj
                    new_rem_g = rem_mem[g] + sj - si
                    new_w_g = weight_sum[g] - wj + wi
                    new_max = 0.0
                    for h in range(gpu_num):
                        if h == worst_g:
                            denom = new_rem_worst
                            kv = (new_w_worst / denom) if denom > 1e-12 else (0.0 if new_w_worst <= 1e-12 else float('inf'))
                        elif h == g:
                            denom = new_rem_g
                            kv = (new_w_g / denom) if denom > 1e-12 else (0.0 if new_w_g <= 1e-12 else float('inf'))
                        else:
                            denom = rem_mem[h]
                            kv = (weight_sum[h] / denom) if denom > 1e-12 else (0.0 if weight_sum[h] <= 1e-12 else float('inf'))
                        if kv > new_max:
                            new_max = kv
                    if new_max + 1e-9 < best_new_max:
                        best_new_max = new_max
                        best_op = ('swap', i, j, worst_g, g)

        if best_op is not None and best_new_max + 1e-9 < cur_max:
            improved = True
            if best_op[0] == 'move':
                _, i, g_from, g_to = best_op
                apply_move_single(i, g_from, g_to)
            else:
                _, i, j, g1, g2 = best_op
                apply_swap(i, j, g1, g2)
            cur_max, _ = current_max_kvpr()
            if cur_max + 1e-12 < best_max:
                best_max = cur_max
                best_state = [list(lst) for lst in gpu_to_idx]
                best_rem = list(rem_mem)
                best_wsum = list(weight_sum)

    T = 4.0
    cooling = 0.96
    max_iter = 1200
    rng = random.Random(42)

    def eval_max_kv() -> float:
        mx = 0.0
        for g in range(gpu_num):
            kv = kvpr_of(g)
            if kv > mx:
                mx = kv
        return mx

    cur_best = eval_max_kv()
    for _ in range(max_iter):
        if rng.random() < 0.6:
            i = rng.randrange(n)
            g_from = assigned_gpu[i]
            targets = [g for g in range(gpu_num) if g != g_from and rem_mem[g] >= sizes[i] - 1e-12]
            if not targets:
                T *= cooling
                continue
            g_to = rng.choice(targets)
            apply_move_single(i, g_from, g_to)
            new_max = eval_max_kv()
            if new_max < cur_best or (T > 1e-4 and rng.random() < math.exp((cur_best - new_max) / T)):
                cur_best = new_max
                if cur_best + 1e-12 < best_max:
                    best_max = cur_best
                    best_state = [list(lst) for lst in gpu_to_idx]
                    best_rem = list(rem_mem)
                    best_wsum = list(weight_sum)
            else:
                apply_move_single(i, g_to, g_from)
        else:
            i = rng.randrange(n)
            g1 = assigned_gpu[i]
            others = [g for g in range(gpu_num) if g != g1 and gpu_to_idx[g]]
            if not others:
                T *= cooling
                continue
            g2 = rng.choice(others)
            j = rng.choice(gpu_to_idx[g2])
            if rem_mem[g1] + sizes[i] - sizes[j] < -1e-12 or rem_mem[g2] + sizes[j] - sizes[i] < -1e-12:
                T *= cooling
                continue
            apply_swap(i, j, g1, g2)
            new_max = eval_max_kv()
            if new_max < cur_best or (T > 1e-4 and rng.random() < math.exp((cur_best - new_max) / T)):
                cur_best = new_max
                if cur_best + 1e-12 < best_max:
                    best_max = cur_best
                    best_state = [list(lst) for lst in gpu_to_idx]
                    best_rem = list(rem_mem)
                    best_wsum = list(weight_sum)
            else:
                apply_swap(i, j, g2, g1)
        T *= cooling
        if T < 1e-4:
            break

    final_idx = best_state
    result: Dict[int, List[Model]] = {g: [] for g in range(gpu_num)}
    for g in range(gpu_num):
        result[g] = [models[i] for i in final_idx[g]]

    for g in range(gpu_num):
        mem = sum(m.model_size for m in result[g])
        if mem > M + 1e-9:
            for m in list(result[g]):
                placed = False
                for h in range(gpu_num):
                    if h == g:
                        continue
                    if sum(x.model_size for x in result[h]) + m.model_size <= M + 1e-9:
                        result[g].remove(m)
                        result[h].append(m)
                        placed = True
                        break
                if not placed:
                    pass
                mem = sum(x.model_size for x in result[g])
                if mem <= M + 1e-9:
                    break

    return result

from dataclasses import dataclass
from typing import List, Dict, Tuple, Set, Optional
import math
import random

GPU_MEM_SIZE = 80  # GB

@dataclass
class Model:
    model_name: str
    model_size: int   # GB
    req_rate: int     # requests per second
    slo: int          # service level objective (latency target)
    cur_gpu_id: int   # current GPU assignment (can be ignored)

def compute_model_placement(gpu_num: int, models: list[Model]) -> dict[int, list[Model]]:
    M = GPU_MEM_SIZE
    n = len(models)
    if n == 0:
        return {g: [] for g in range(gpu_num)}

    sizes = [m.model_size for m in models]
    weights = [m.req_rate / m.slo for m in models]

    for i, s in enumerate(sizes):
        if s > M:
            raise ValueError(f"Model {models[i].model_name} size {s} exceeds GPU capacity {M}.")

    total_size = sum(sizes)
    total_w = sum(weights)

    denom = gpu_num * M - total_size
    global_lb = total_w / denom if denom > 1e-12 else float('inf')
    per_model_lb = max((weights[i] / max(M - sizes[i], 1e-12)) for i in range(n))
    tau_low = max(global_lb, per_model_lb, 0.0)

    def model_key(i: int) -> Tuple[float, int, float, str]:
        return (weights[i] / max(M - sizes[i], 1e-12), -sizes[i], weights[i], models[i].model_name)
    order = sorted(range(n), key=model_key, reverse=True)

    def greedy_upper() -> Tuple[float, Dict[int, List[int]]]:
        used_s = [0] * gpu_num
        used_w = [0.0] * gpu_num
        placement_idx: Dict[int, List[int]] = {g: [] for g in range(gpu_num)}
        tabu = set()
        max_depth = 3 * gpu_num
        depth_count = {g: 0 for g in range(gpu_num)}

        for i in order:
            if i in tabu:
                continue

            candidates = [g for g in range(gpu_num) if used_s[g] + sizes[i] < M - 1e-12]
            if not candidates:
                best_g = min(range(gpu_num), key=lambda g: used_w[g] / max(M - used_s[g], 1e-12))
                used_s[best_g] += sizes[i]
                used_w[best_g] += weights[i]
                placement_idx[best_g].append(i)
                continue

            scores = []
            for g in candidates:
                s_after = used_s[g] + sizes[i]
                w_after = used_w[g] + weights[i]
                denom_g = M - s_after
                kvpr_g = w_after / denom_g if denom_g > 1e-12 else float('inf')
                worst = kvpr_g
                for h in range(gpu_num):
                    if h == g:
                        continue
                    dh = M - used_s[h]
                    if dh <= 1e-12:
                        if used_w[h] > 0:
                            worst = float('inf')
                            break
                        continue
                    worst = max(worst, used_w[h] / dh)
                score = -worst
                scores.append((score, g))

            if not scores:
                best_g = min(range(gpu_num), key=lambda g: used_w[g] / max(M - used_s[g], 1e-12))
                used_s[best_g] += sizes[i]
                used_w[best_g] += weights[i]
                placement_idx[best_g].append(i)
                continue

            max_score = max(s for s, _ in scores)
            exp_scores = [math.exp(s - max_score) for s, _ in scores]
            total = sum(exp_scores)
            probs = [e / total for e in exp_scores]
            chosen_g = random.choices([g for _, g in scores], weights=probs, k=1)[0]

            used_s[chosen_g] += sizes[i]
            used_w[chosen_g] += weights[i]
            placement_idx[chosen_g].append(i)
            tabu.add(i)
            if len(tabu) > 10:
                tabu.pop()

        max_k = 0.0
        for g in range(gpu_num):
            denom_g = M - used_s[g]
            if denom_g > 1e-12:
                max_k = max(max_k, used_w[g] / denom_g)
            elif used_w[g] > 0:
                max_k = float('inf')
        return max_k, placement_idx

    def feasible_pack(tau: float) -> Tuple[bool, Dict[int, List[int]]]:
        used_s = [0] * gpu_num
        used_w = [0.0] * gpu_num
        placement: Dict[int, List[int]] = {g: [] for g in range(gpu_num)}
        assigned = [-1] * n

        def gpu_order_for_item(i: int) -> List[int]:
            cands = []
            for g in range(gpu_num):
                s_after = used_s[g] + sizes[i]
                if s_after >= M - 1e-12:
                    continue
                w_after = used_w[g] + weights[i]
                if w_after <= tau * (M - s_after) + 1e-12:
                    denom_g = M - s_after
                    kv_est = w_after / denom_g if denom_g > 1e-12 else float('inf')
                    score = kv_est + 1e-6 * (M - s_after)
                    cands.append((score, g))
            cands.sort(key=lambda x: (x[0], x[1]))
            picked = [g for (_, g) in cands]
            picked += [g for g in range(gpu_num) if g not in picked]
            return picked

        def place_with_relocation(i: int, visiting: Set[int], banned: Dict[int, Set[int]]) -> bool:
            if i in visiting:
                return False
            visiting.add(i)

            for g in gpu_order_for_item(i):
                if g in banned.get(i, set()):
                    continue
                s_after = used_s[g] + sizes[i]
                if s_after >= M - 1e-12:
                    continue
                w_after = used_w[g] + weights[i]
                if w_after <= tau * (M - s_after) + 1e-12:
                    placement[g].append(i)
                    used_s[g] += sizes[i]
                    used_w[g] += weights[i]
                    assigned[i] = g
                    visiting.remove(i)
                    return True

            gpu_candidates = []
            for g in range(gpu_num):
                if g in banned.get(i, set()):
                    continue
                s_after = used_s[g] + sizes[i]
                w_after = used_w[g] + weights[i]
                mem_def = max(0.0, s_after - (M - 1e-12))
                lin_def = max(0.0, w_after - (tau * (M - s_after)))
                deficit = mem_def + lin_def
                gpu_candidates.append((deficit, g))
            gpu_candidates.sort(key=lambda x: (x[0], x[1]))

            for _, g in gpu_candidates:
                movable_js = []
                for j in placement[g]:
                    if j in visiting:
                        continue
                    s2 = used_s[g] - sizes[j] + sizes[i]
                    w2 = used_w[g] - weights[j] + weights[i]
                    if s2 < M - 1e-12 and w2 <= tau * (M - s2) + 1e-12:
                        alt = 0
                        for h in range(gpu_num):
                            if h == g:
                                continue
                            if h in banned.get(j, set()):
                                continue
                            ss = used_s[h] + sizes[j]
                            if ss >= M - 1e-12:
                                continue
                            ww = used_w[h] + weights[j]
                            if ww <= tau * (M - ss) + 1e-12:
                                alt += 1
                        movable_js.append((-(alt), j))
                movable_js.sort()
                for _, j in movable_js:
                    placement[g].remove(j)
                    used_s[g] -= sizes[j]
                    used_w[g] -= weights[j]
                    assigned[j] = -1
                    banned.setdefault(j, set()).add(g)
                    if place_with_relocation(j, visiting, banned):
                        s2 = used_s[g] + sizes[i]
                        w2 = used_w[g] + weights[i]
                        if s2 < M - 1e-12 and w2 <= tau * (M - s2) + 1e-12:
                            placement[g].append(i)
                            used_s[g] += sizes[i]
                            used_w[g] += weights[i]
                            assigned[i] = g
                            visiting.remove(i)
                            return True
                    banned[j].discard(g)
                    placement[g].append(j)
                    used_s[g] += sizes[j]
                    used_w[g] += weights[j]
                    assigned[j] = g
            visiting.remove(i)
            return False

        for i in order:
            if not place_with_relocation(i, set(), {}):
                return False, {}
        return True, placement

    ub_val, ub_assign_idx = greedy_upper()
    tau_high = ub_val if math.isfinite(ub_val) and ub_val > tau_low else max(tau_low * 2.0, tau_low + 1.0)

    best_tau = float('inf')
    best_assign_idx: Dict[int, List[int]] = {}

    if math.isfinite(ub_val):
        ok, pack = feasible_pack(ub_val)
        if ok:
            best_tau = ub_val
            best_assign_idx = pack

    big_tau = max(tau_high * 8.0, tau_low + 100.0)
    ok_big, pack_big = feasible_pack(big_tau)
    if ok_big:
        tau_high = min(tau_high, big_tau)
        if big_tau < best_tau:
            best_tau = big_tau
            best_assign_idx = pack_big

    if not best_assign_idx:
        ok, pack = feasible_pack(tau_high)
        if ok:
            best_tau = tau_high
            best_assign_idx = pack

    if not best_assign_idx:
        best_assign_idx = ub_assign_idx

    left = tau_low
    right = max(tau_high, left + 1.0)
    ok_r, pack_r = feasible_pack(right)
    if ok_r and right < best_tau:
        best_tau = right
        best_assign_idx = pack_r

    for _ in range(24):
        mid = 0.5 * (left + right)
        if not math.isfinite(mid):
            break
        ok, pack = feasible_pack(mid)
        if ok:
            right = mid
            if mid < best_tau:
                best_tau = mid
                best_assign_idx = pack
        else:
            left = mid
        if right - left <= max(1e-6, 1e-6 * right):
            break

    if not best_assign_idx:
        best_assign_idx = ub_assign_idx

    gpu_to_idx: List[List[int]] = [[] for _ in range(gpu_num)]
    for g, lst in best_assign_idx.items():
        for i in lst:
            gpu_to_idx[g].append(i)

    assigned_gpu = [-1] * n
    for g in range(gpu_num):
        for i in gpu_to_idx[g]:
            assigned_gpu[i] = g

    for i in range(n):
        if assigned_gpu[i] == -1:
            rems = [M - sum(sizes[k] for k in gpu_to_idx[g]) for g in range(gpu_num)]
            g = max(range(gpu_num), key=lambda gg: (rems[gg] - sizes[i], rems[gg]))
            gpu_to_idx[g].append(i)
            assigned_gpu[i] = g

    rem_mem = [M - sum(sizes[i] for i in gpu_to_idx[g]) for g in range(gpu_num)]
    weight_sum = [sum(weights[i] for i in gpu_to_idx[g]) for g in range(gpu_num)]

    def kvpr_of(g: int) -> float:
        denom_g = rem_mem[g]
        if denom_g <= 1e-12:
            return float('inf') if weight_sum[g] > 0 else 0.0
        return weight_sum[g] / denom_g

    def current_max_kvpr() -> Tuple[float, int]:
        vals = [kvpr_of(g) for g in range(gpu_num)]
        mx = max(vals)
        return mx, int(max(range(gpu_num), key=lambda x: vals[x]))

    best_max, _ = current_max_kvpr()
    best_state = [list(lst) for lst in gpu_to_idx]
    best_rem = list(rem_mem)
    best_wsum = list(weight_sum)

    def apply_move_single(i: int, g_from: int, g_to: int):
        gpu_to_idx[g_from].remove(i)
        gpu_to_idx[g_to].append(i)
        assigned_gpu[i] = g_to
        rem_mem[g_from] += sizes[i]
        rem_mem[g_to] -= sizes[i]
        weight_sum[g_from] -= weights[i]
        weight_sum[g_to] += weights[i]

    def apply_swap(i: int, j: int, g1: int, g2: int):
        gpu_to_idx[g1].remove(i)
        gpu_to_idx[g2].remove(j)
        gpu_to_idx[g1].append(j)
        gpu_to_idx[g2].append(i)
        assigned_gpu[i] = g2
        assigned_gpu[j] = g1
        rem_mem[g1] += sizes[i] - sizes[j]
        rem_mem[g2] += sizes[j] - sizes[i]
        weight_sum[g1] += weights[j] - weights[i]
        weight_sum[g2] += weights[i] - weights[j]

    max_hill_iters = 2000
    improved = True
    iters = 0
    while improved and iters < max_hill_iters:
        iters += 1
        improved = False
        cur_max, worst_g = current_max_kvpr()
        best_new_max = cur_max
        best_op = None

        for i in list(gpu_to_idx[worst_g]):
            si, wi = sizes[i], weights[i]
            for g in range(gpu_num):
                if g == worst_g:
                    continue
                if rem_mem[g] >= si - 1e-12:
                    new_rem_worst = rem_mem[worst_g] + si
                    new_w_worst = weight_sum[worst_g] - wi
                    new_rem_g = rem_mem[g] - si
                    new_w_g = weight_sum[g] + wi
                    new_max = 0.0
                    for h in range(gpu_num):
                        if h == worst_g:
                            denom = new_rem_worst
                            kv = (new_w_worst / denom) if denom > 1e-12 else (0.0 if new_w_worst <= 1e-12 else float('inf'))
                        elif h == g:
                            denom = new_rem_g
                            kv = (new_w_g / denom) if denom > 1e-12 else (0.0 if new_w_g <= 1e-12 else float('inf'))
                        else:
                            denom = rem_mem[h]
                            kv = (weight_sum[h] / denom) if denom > 1e-12 else (0.0 if weight_sum[h] <= 1e-12 else float('inf'))
                        if kv > new_max:
                            new_max = kv
                    if new_max + 1e-9 < best_new_max:
                        best_new_max = new_max
                        best_op = ('move', i, worst_g, g)

        for g in range(gpu_num):
            if g == worst_g:
                continue
            for i in list(gpu_to_idx[worst_g]):
                si, wi = sizes[i], weights[i]
                for j in list(gpu_to_idx[g]):
                    sj, wj = sizes[j], weights[j]
                    if rem_mem[worst_g] + si - sj < -1e-12 or rem_mem[g] + sj - si < -1e-12:
                        continue
                    new_rem_worst = rem_mem[worst_g] + si - sj
                    new_w_worst = weight_sum[worst_g] - wi + wj
                    new_rem_g = rem_mem[g] + sj - si
                    new_w_g = weight_sum[g] - wj + wi
                    new_max = 0.0
                    for h in range(gpu_num):
                        if h == worst_g:
                            denom = new_rem_worst
                            kv = (new_w_worst / denom) if denom > 1e-12 else (0.0 if new_w_worst <= 1e-12 else float('inf'))
                        elif h == g:
                            denom = new_rem_g
                            kv = (new_w_g / denom) if denom > 1e-12 else (0.0 if new_w_g <= 1e-12 else float('inf'))
                        else:
                            denom = rem_mem[h]
                            kv = (weight_sum[h] / denom) if denom > 1e-12 else (0.0 if weight_sum[h] <= 1e-12 else float('inf'))
                        if kv > new_max:
                            new_max = kv
                    if new_max + 1e-9 < best_new_max:
                        best_new_max = new_max
                        best_op = ('swap', i, j, worst_g, g)

        if best_op is not None and best_new_max + 1e-9 < cur_max:
            improved = True
            if best_op[0] == 'move':
                _, i, g_from, g_to = best_op
                apply_move_single(i, g_from, g_to)
            else:
                _, i, j, g1, g2 = best_op
                apply_swap(i, j, g1, g2)
            cur_max, _ = current_max_kvpr()
            if cur_max + 1e-12 < best_max:
                best_max = cur_max
                best_state = [list(lst) for lst in gpu_to_idx]
                best_rem = list(rem_mem)
                best_wsum = list(weight_sum)

    T = 4.0
    cooling = 0.96
    max_iter = 1200
    rng = random.Random(42)

    def eval_max_kv() -> float:
        mx = 0.0
        for g in range(gpu_num):
            kv = kvpr_of(g)
            if kv > mx:
                mx = kv
        return mx

    cur_best = eval_max_kv()
    for _ in range(max_iter):
        if rng.random() < 0.6:
            i = rng.randrange(n)
            g_from = assigned_gpu[i]
            targets = [g for g in range(gpu_num) if g != g_from and rem_mem[g] >= sizes[i] - 1e-12]
            if not targets:
                T *= cooling
                continue
            g_to = rng.choice(targets)
            apply_move_single(i, g_from, g_to)
            new_max = eval_max_kv()
            improvement = cur_best - new_max
            if improvement > 1e-6 or (T > 1e-4 and rng.random() < math.exp(improvement / T)):
                cur_best = new_max
                if cur_best + 1e-12 < best_max:
                    best_max = cur_best
                    best_state = [list(lst) for lst in gpu_to_idx]
                    best_rem = list(rem_mem)
                    best_wsum = list(weight_sum)
            else:
                apply_move_single(i, g_to, g_from)
        else:
            i = rng.randrange(n)
            g1 = assigned_gpu[i]
            others = [g for g in range(gpu_num) if g != g1 and gpu_to_idx[g]]
            if not others:
                T *= cooling
                continue
            g2 = rng.choice(others)
            j = rng.choice(gpu_to_idx[g2])
            if rem_mem[g1] + sizes[i] - sizes[j] < -1e-12 or rem_mem[g2] + sizes[j] - sizes[i] < -1e-12:
                T *= cooling
                continue
            apply_swap(i, j, g1, g2)
            new_max = eval_max_kv()
            improvement = cur_best - new_max
            if improvement > 1e-6 or (T > 1e-4 and rng.random() < math.exp(improvement / T)):
                cur_best = new_max
                if cur_best + 1e-12 < best_max:
                    best_max = cur_best
                    best_state = [list(lst) for lst in gpu_to_idx]
                    best_rem = list(rem_mem)
                    best_wsum = list(weight_sum)
            else:
                apply_swap(i, j, g2, g1)
        T *= cooling
        if T < 1e-4:
            break

    final_idx = best_state
    result: Dict[int, List[Model]] = {g: [] for g in range(gpu_num)}
    for g in range(gpu_num):
        result[g] = [models[i] for i in final_idx[g]]

    for g in range(gpu_num):
        mem = sum(m.model_size for m in result[g])
        if mem > M + 1e-9:
            for m in list(result[g]):
                placed = False
                for h in range(gpu_num):
                    if h == g:
                        continue
                    if sum(x.model_size for x in result[h]) + m.model_size <= M + 1e-9:
                        result[g].remove(m)
                        result[h].append(m)
                        placed = True
                        break
                if not placed:
                    pass
                mem = sum(x.model_size for x in result[g])
                if mem <= M + 1e-9:
                    break

    return result

from dataclasses import dataclass
from typing import List, Dict, Tuple, Set, Optional
import math
import random

GPU_MEM_SIZE = 80  # GB

@dataclass
class Model:
    model_name: str
    model_size: int   # GB
    req_rate: int     # requests per second
    slo: int          # service level objective (latency target)
    cur_gpu_id: int   # current GPU assignment (can be ignored)

def compute_model_placement(gpu_num: int, models: list[Model]) -> dict[int, list[Model]]:
    M = GPU_MEM_SIZE
    n = len(models)
    if n == 0:
        return {g: [] for g in range(gpu_num)}

    sizes = [m.model_size for m in models]
    weights = [m.req_rate / m.slo for m in models]

    for i, s in enumerate(sizes):
        if s > M:
            raise ValueError(f"Model {models[i].model_name} size {s} exceeds GPU capacity {M}.")

    total_size = sum(sizes)
    total_w = sum(weights)

    denom = gpu_num * M - total_size
    global_lb = total_w / denom if denom > 1e-9 else float('inf')
    per_model_lb = max((weights[i] / max(M - sizes[i], 1e-9)) for i in range(n))
    tau_low = max(global_lb, per_model_lb, 0.0)

    def model_key(i: int) -> Tuple[float, int, float, str]:
        return (weights[i] / max(M - sizes[i], 1e-9), -sizes[i], weights[i], models[i].model_name)
    order = sorted(range(n), key=model_key, reverse=True)

    def greedy_upper() -> Tuple[float, Dict[int, List[int]]]:
        used_s = [0] * gpu_num
        used_w = [0.0] * gpu_num
        placement_idx: Dict[int, List[int]] = {g: [] for g in range(gpu_num)}
        for i in order:
            best_g = None
            best_max = float('inf')
            candidates = [g for g in range(gpu_num) if used_s[g] + sizes[i] < M - 1e-9]
            for g in candidates:
                s_after = used_s[g] + sizes[i]
                w_after = used_w[g] + weights[i]
                denom_g = M - s_after
                kvpr_g = w_after / denom_g if denom_g > 1e-9 else float('inf')
                worst = kvpr_g
                for h in range(gpu_num):
                    if h == g:
                        continue
                    dh = M - used_s[h]
                    if dh <= 1e-9:
                        if used_w[h] > 0:
                            worst = float('inf')
                            break
                        continue
                    worst = max(worst, used_w[h] / dh)
                if worst < best_max:
                    best_max = worst
                    best_g = g
            if best_g is None:
                best_g = max(range(gpu_num), key=lambda g: used_s[g])
                if used_s[best_g] + sizes[i] >= M - 1e-9:
                    best_g = min(range(gpu_num), key=lambda g: used_w[g] / max(M - used_s[g], 1e-9))
            used_s[best_g] += sizes[i]
            used_w[best_g] += weights[i]
            placement_idx[best_g].append(i)
        max_k = 0.0
        for g in range(gpu_num):
            denom_g = M - used_s[g]
            if denom_g > 1e-9:
                max_k = max(max_k, used_w[g] / denom_g)
            elif used_w[g] > 0:
                max_k = float('inf')
        return max_k, placement_idx

    def feasible_pack(tau: float) -> Tuple[bool, Dict[int, List[int]]]:
        used_s = [0] * gpu_num
        used_w = [0.0] * gpu_num
        placement: Dict[int, List[int]] = {g: [] for g in range(gpu_num)}
        assigned = [-1] * n

        def gpu_order_for_item(i: int) -> List[int]:
            cands = []
            for g in range(gpu_num):
                s_after = used_s[g] + sizes[i]
                if s_after >= M - 1e-9:
                    continue
                w_after = used_w[g] + weights[i]
                if w_after <= tau * (M - s_after) + 1e-9:
                    denom_g = M - s_after
                    kv_est = w_after / denom_g if denom_g > 1e-9 else float('inf')
                    score = kv_est + 1e-6 * (M - s_after)
                    cands.append((score, g))
            cands.sort(key=lambda x: (x[0], x[1]))
            picked = [g for (_, g) in cands]
            picked += [g for g in range(gpu_num) if g not in picked]
            return picked

        def place_with_relocation(i: int, visiting: Set[int], banned: Dict[int, Set[int]]) -> bool:
            if i in visiting:
                return False
            visiting.add(i)

            for g in gpu_order_for_item(i):
                if g in banned.get(i, set()):
                    continue
                s_after = used_s[g] + sizes[i]
                if s_after >= M - 1e-9:
                    continue
                w_after = used_w[g] + weights[i]
                if w_after <= tau * (M - s_after) + 1e-9:
                    placement[g].append(i)
                    used_s[g] += sizes[i]
                    used_w[g] += weights[i]
                    assigned[i] = g
                    visiting.remove(i)
                    return True

            gpu_candidates = []
            for g in range(gpu_num):
                if g in banned.get(i, set()):
                    continue
                s_after = used_s[g] + sizes[i]
                w_after = used_w[g] + weights[i]
                mem_def = max(0.0, s_after - (M - 1e-9))
                lin_def = max(0.0, w_after - (tau * (M - s_after)))
                deficit = mem_def + lin_def
                gpu_candidates.append((deficit, g))
            gpu_candidates.sort(key=lambda x: (x[0], x[1]))

            for _, g in gpu_candidates:
                movable_js = []
                for j in placement[g]:
                    if j in visiting:
                        continue
                    s2 = used_s[g] - sizes[j] + sizes[i]
                    w2 = used_w[g] - weights[j] + weights[i]
                    if s2 < M - 1e-9 and w2 <= tau * (M - s2) + 1e-9:
                        alt = 0
                        for h in range(gpu_num):
                            if h == g:
                                continue
                            if h in banned.get(j, set()):
                                continue
                            ss = used_s[h] + sizes[j]
                            if ss >= M - 1e-9:
                                continue
                            ww = used_w[h] + weights[j]
                            if ww <= tau * (M - ss) + 1e-9:
                                alt += 1
                        movable_js.append((-(alt), j))
                movable_js.sort()
                for _, j in movable_js:
                    placement[g].remove(j)
                    used_s[g] -= sizes[j]
                    used_w[g] -= weights[j]
                    assigned[j] = -1
                    banned.setdefault(j, set()).add(g)
                    if place_with_relocation(j, visiting, banned):
                        s2 = used_s[g] + sizes[i]
                        w2 = used_w[g] + weights[i]
                        if s2 < M - 1e-9 and w2 <= tau * (M - s2) + 1e-9:
                            placement[g].append(i)
                            used_s[g] += sizes[i]
                            used_w[g] += weights[i]
                            assigned[i] = g
                            visiting.remove(i)
                            return True
                    banned[j].discard(g)
                    placement[g].append(j)
                    used_s[g] += sizes[j]
                    used_w[g] += weights[j]
                    assigned[j] = g
            visiting.remove(i)
            return False

        for i in order:
            if not place_with_relocation(i, set(), {}):
                return False, {}
        return True, placement

    ub_val, ub_assign_idx = greedy_upper()
    tau_high = ub_val if math.isfinite(ub_val) and ub_val > tau_low else max(tau_low * 2.0, tau_low + 1.0)

    best_tau = float('inf')
    best_assign_idx: Dict[int, List[int]] = {}

    if math.isfinite(ub_val):
        ok, pack = feasible_pack(ub_val)
        if ok:
            best_tau = ub_val
            best_assign_idx = pack

    big_tau = max(tau_high * 8.0, tau_low + 100.0)
    ok_big, pack_big = feasible_pack(big_tau)
    if ok_big:
        tau_high = min(tau_high, big_tau)
        if big_tau < best_tau:
            best_tau = big_tau
            best_assign_idx = pack_big

    if not best_assign_idx:
        ok, pack = feasible_pack(tau_high)
        if ok:
            best_tau = tau_high
            best_assign_idx = pack

    if not best_assign_idx:
        best_assign_idx = ub_assign_idx

    left = tau_low
    right = max(tau_high, left + 1.0)
    ok_r, pack_r = feasible_pack(right)
    if ok_r and right < best_tau:
        best_tau = right
        best_assign_idx = pack_r

    for _ in range(24):
        mid = 0.5 * (left + right)
        if not math.isfinite(mid):
            break
        ok, pack = feasible_pack(mid)
        if ok:
            right = mid
            if mid < best_tau:
                best_tau = mid
                best_assign_idx = pack
        else:
            left = mid
        if right - left <= max(1e-9, 1e-9 * right):
            break

    if not best_assign_idx:
        best_assign_idx = ub_assign_idx

    gpu_to_idx: List[List[int]] = [[] for _ in range(gpu_num)]
    for g, lst in best_assign_idx.items():
        for i in lst:
            gpu_to_idx[g].append(i)

    assigned_gpu = [-1] * n
    for g in range(gpu_num):
        for i in gpu_to_idx[g]:
            assigned_gpu[i] = g

    for i in range(n):
        if assigned_gpu[i] == -1:
            rems = [M - sum(sizes[k] for k in gpu_to_idx[g]) for g in range(gpu_num)]
            g = max(range(gpu_num), key=lambda gg: (rems[gg] - sizes[i], rems[gg]))
            gpu_to_idx[g].append(i)
            assigned_gpu[i] = g

    rem_mem = [M - sum(sizes[i] for i in gpu_to_idx[g]) for g in range(gpu_num)]
    weight_sum = [sum(weights[i] for i in gpu_to_idx[g]) for g in range(gpu_num)]

    def kvpr_of(g: int) -> float:
        denom_g = rem_mem[g]
        if denom_g <= 1e-9:
            return float('inf') if weight_sum[g] > 0 else 0.0
        return weight_sum[g] / denom_g

    def current_max_kvpr() -> Tuple[float, int]:
        vals = [kvpr_of(g) for g in range(gpu_num)]
        mx = max(vals)
        return mx, int(max(range(gpu_num), key=lambda x: vals[x]))

    best_max, _ = current_max_kvpr()
    best_state = [list(lst) for lst in gpu_to_idx]
    best_rem = list(rem_mem)
    best_wsum = list(weight_sum)

    def apply_move_single(i: int, g_from: int, g_to: int):
        gpu_to_idx[g_from].remove(i)
        gpu_to_idx[g_to].append(i)
        assigned_gpu[i] = g_to
        rem_mem[g_from] += sizes[i]
        rem_mem[g_to] -= sizes[i]
        weight_sum[g_from] -= weights[i]
        weight_sum[g_to] += weights[i]

    def apply_swap(i: int, j: int, g1: int, g2: int):
        gpu_to_idx[g1].remove(i)
        gpu_to_idx[g2].remove(j)
        gpu_to_idx[g1].append(j)
        gpu_to_idx[g2].append(i)
        assigned_gpu[i] = g2
        assigned_gpu[j] = g1
        rem_mem[g1] += sizes[i] - sizes[j]
        rem_mem[g2] += sizes[j] - sizes[i]
        weight_sum[g1] += weights[j] - weights[i]
        weight_sum[g2] += weights[i] - weights[j]

    max_hill_iters = 2000
    improved = True
    iters = 0
    while improved and iters < max_hill_iters:
        iters += 1
        improved = False
        cur_max, worst_g = current_max_kvpr()
        best_new_max = cur_max
        best_op = None

        for i in list(gpu_to_idx[worst_g]):
            si, wi = sizes[i], weights[i]
            for g in range(gpu_num):
                if g == worst_g:
                    continue
                if rem_mem[g] >= si - 1e-9:
                    new_rem_worst = rem_mem[worst_g] + si
                    new_w_worst = weight_sum[worst_g] - wi
                    new_rem_g = rem_mem[g] - si
                    new_w_g = weight_sum[g] + wi
                    new_max = 0.0
                    for h in range(gpu_num):
                        if h == worst_g:
                            denom = new_rem_worst
                            kv = (new_w_worst / denom) if denom > 1e-9 else (0.0 if new_w_worst <= 1e-9 else float('inf'))
                        elif h == g:
                            denom = new_rem_g
                            kv = (new_w_g / denom) if denom > 1e-9 else (0.0 if new_w_g <= 1e-9 else float('inf'))
                        else:
                            denom = rem_mem[h]
                            kv = (weight_sum[h] / denom) if denom > 1e-9 else (0.0 if weight_sum[h] <= 1e-9 else float('inf'))
                        if kv > new_max:
                            new_max = kv
                    if new_max + 1e-9 < best_new_max:
                        best_new_max = new_max
                        best_op = ('move', i, worst_g, g)

        for g in range(gpu_num):
            if g == worst_g:
                continue
            for i in list(gpu_to_idx[worst_g]):
                si, wi = sizes[i], weights[i]
                for j in list(gpu_to_idx[g]):
                    sj, wj = sizes[j], weights[j]
                    if rem_mem[worst_g] + si - sj < -1e-9 or rem_mem[g] + sj - si < -1e-9:
                        continue
                    new_rem_worst = rem_mem[worst_g] + si - sj
                    new_w_worst = weight_sum[worst_g] - wi + wj
                    new_rem_g = rem_mem[g] + sj - si
                    new_w_g = weight_sum[g] - wj + wi
                    new_max = 0.0
                    for h in range(gpu_num):
                        if h == worst_g:
                            denom = new_rem_worst
                            kv = (new_w_worst / denom) if denom > 1e-9 else (0.0 if new_w_worst <= 1e-9 else float('inf'))
                        elif h == g:
                            denom = new_rem_g
                            kv = (new_w_g / denom) if denom > 1e-9 else (0.0 if new_w_g <= 1e-9 else float('inf'))
                        else:
                            denom = rem_mem[h]
                            kv = (weight_sum[h] / denom) if denom > 1e-9 else (0.0 if weight_sum[h] <= 1e-9 else float('inf'))
                        if kv > new_max:
                            new_max = kv
                    if new_max + 1e-9 < best_new_max:
                        best_new_max = new_max
                        best_op = ('swap', i, j, worst_g, g)

        if best_op is not None and best_new_max + 1e-9 < cur_max:
            improved = True
            if best_op[0] == 'move':
                _, i, g_from, g_to = best_op
                apply_move_single(i, g_from, g_to)
            else:
                _, i, j, g1, g2 = best_op
                apply_swap(i, j, g1, g2)
            cur_max, _ = current_max_kvpr()
            if cur_max + 1e-9 < best_max:
                best_max = cur_max
                best_state = [list(lst) for lst in gpu_to_idx]
                best_rem = list(rem_mem)
                best_wsum = list(weight_sum)

    T = 4.0
    cooling = 0.96
    max_iter = 1200
    rng = random.Random(42)

    def eval_max_kv() -> float:
        mx = 0.0
        for g in range(gpu_num):
            kv = kvpr_of(g)
            if kv > mx:
                mx = kv
        return mx

    cur_best = eval_max_kv()
    for _ in range(max_iter):
        if rng.random() < 0.6:
            i = rng.randrange(n)
            g_from = assigned_gpu[i]
            targets = [g for g in range(gpu_num) if g != g_from and rem_mem[g] >= sizes[i] - 1e-9]
            if not targets:
                T *= cooling
                continue
            g_to = rng.choice(targets)
            apply_move_single(i, g_from, g_to)
            new_max = eval_max_kv()
            if new_max < cur_best or (T > 1e-4 and rng.random() < math.exp((cur_best - new_max) / T)):
                cur_best = new_max
                if cur_best + 1e-9 < best_max:
                    best_max = cur_best
                    best_state = [list(lst) for lst in gpu_to_idx]
                    best_rem = list(rem_mem)
                    best_wsum = list(weight_sum)
            else:
                apply_move_single(i, g_to, g_from)
        else:
            i = rng.randrange(n)
            g1 = assigned_gpu[i]
            others = [g for g in range(gpu_num) if g != g1 and gpu_to_idx[g]]
            if not others:
                T *= cooling
                continue
            g2 = rng.choice(others)
            j = rng.choice(gpu_to_idx[g2])
            if rem_mem[g1] + sizes[i] - sizes[j] < -1e-9 or rem_mem[g2] + sizes[j] - sizes[i] < -1e-9:
                T *= cooling
                continue
            apply_swap(i, j, g1, g2)
            new_max = eval_max_kv()
            if new_max < cur_best or (T > 1e-4 and rng.random() < math.exp((cur_best - new_max) / T)):
                cur_best = new_max
                if cur_best + 1e-9 < best_max:
                    best_max = cur_best
                    best_state = [list(lst) for lst in gpu_to_idx]
                    best_rem = list(rem_mem)
                    best_wsum = list(weight_sum)
            else:
                apply_swap(i, j, g2, g1)
        T *= cooling
        if T < 1e-4:
            break

    final_idx = best_state
    result: Dict[int, List[Model]] = {g: [] for g in range(gpu_num)}
    for g in range(gpu_num):
        result[g] = [models[i] for i in final_idx[g]]

    for g in range(gpu_num):
        mem = sum(m.model_size for m in result[g])
        if mem > M + 1e-9:
            for m in list(result[g]):
                placed = False
                for h in range(gpu_num):
                    if h == g:
                        continue
                    if sum(x.model_size for x in result[h]) + m.model_size <= M + 1e-9:
                        result[g].remove(m)
                        result[h].append(m)
                        placed = True
                        break
                if not placed:
                    pass
                mem = sum(x.model_size for x in result[g])
                if mem <= M + 1e-9:
                    break

    return result

from dataclasses import dataclass
from typing import List, Dict, Tuple, Set, Optional
import math
import random

GPU_MEM_SIZE = 80  # GB

@dataclass
class Model:
    model_name: str
    model_size: int   # GB
    req_rate: int     # requests per second
    slo: int          # service level objective (latency target)
    cur_gpu_id: int   # current GPU assignment (can be ignored)

def compute_model_placement(gpu_num: int, models: list[Model]) -> dict[int, list[Model]]:
    M = GPU_MEM_SIZE
    n = len(models)
    if n == 0:
        return {g: [] for g in range(gpu_num)}

    sizes = [m.model_size for m in models]
    weights = [m.req_rate / m.slo for m in models]

    for i, s in enumerate(sizes):
        if s > M:
            raise ValueError(f"Model {models[i].model_name} size {s} exceeds GPU capacity {M}.")

    total_size = sum(sizes)
    total_w = sum(weights)

    denom = gpu_num * M - total_size
    global_lb = total_w / denom if denom > 1e-9 else float('inf')
    per_model_lb = max((weights[i] / max(M - sizes[i], 1e-9)) for i in range(n))
    tau_low = max(global_lb, per_model_lb, 0.0)

    def model_key(i: int) -> Tuple[float, int, float, str]:
        return (weights[i] / max(M - sizes[i], 1e-9), -sizes[i], weights[i], models[i].model_name)
    order = sorted(range(n), key=model_key, reverse=True)

    def greedy_upper() -> Tuple[float, Dict[int, List[int]]]:
        used_s = [0] * gpu_num
        used_w = [0.0] * gpu_num
        placement_idx: Dict[int, List[int]] = {g: [] for g in range(gpu_num)}
        for i in order:
            best_g = None
            best_max = float('inf')
            candidates = [g for g in range(gpu_num) if used_s[g] + sizes[i] < M - 1e-9]
            for g in candidates:
                s_after = used_s[g] + sizes[i]
                w_after = used_w[g] + weights[i]
                denom_g = M - s_after
                kvpr_g = w_after / denom_g if denom_g > 1e-9 else float('inf')
                worst = kvpr_g
                for h in range(gpu_num):
                    if h == g:
                        continue
                    dh = M - used_s[h]
                    if dh <= 1e-9:
                        if used_w[h] > 0:
                            worst = float('inf')
                            break
                        continue
                    worst = max(worst, used_w[h] / dh)
                if worst < best_max:
                    best_max = worst
                    best_g = g
            if best_g is None:
                best_g = max(range(gpu_num), key=lambda g: used_s[g])
                if used_s[best_g] + sizes[i] >= M - 1e-9:
                    best_g = min(range(gpu_num), key=lambda g: used_w[g] / max(M - used_s[g], 1e-9))
            used_s[best_g] += sizes[i]
            used_w[best_g] += weights[i]
            placement_idx[best_g].append(i)
        max_k = 0.0
        for g in range(gpu_num):
            denom_g = M - used_s[g]
            if denom_g > 1e-9:
                max_k = max(max_k, used_w[g] / denom_g)
            elif used_w[g] > 0:
                max_k = float('inf')
        return max_k, placement_idx

