                    # For simplicity, we focus on swaps that could lower the max KVPR
                    diff = max_kvpr - max(compute_kvpr(g) for g in range(gpu_num) if g != gpu_id and g != other_gpu_id) - (model.req_rate / model.slo) / (GPU_MEM_SIZE - sum(m.model_size for m in other_models) - model.model_size)
                    if diff > 1e-9:
                        heapq.heappush(improvements, (-diff, gpu_id, other_gpu_id, model))

    # Execute top improvements up to 50 iterations or when no improvement is possible
    for _ in range(50):
        if not improvements:
            break
        _, src_gpu, dst_gpu, model = heapq.heappop(improvements)
        # Recheck feasibility due to dynamic state
        if (model not in placement[src_gpu] or 
            sum(m.model_size for m in placement[dst_gpu]) + model.model_size > GPU_MEM_SIZE):
            continue
        # Perform swap
        placement[src_gpu].remove(model)
        placement[dst_gpu].append(model)
        # Recompute KVPRs and reinsert improvements
        max_kvpr = max(compute_kvpr(i) for i in range(gpu_num))
        for gpu_id in range(gpu_num):
            for other_model in placement[gpu_id]:
                if other_model is model:
                    continue
                for other_gpu_id in range(gpu_num):
                    if other_gpu_id == gpu_id:
                        continue
                    if sum(m.model_size for m in placement[other_gpu_id]) + other_model.model_size <= GPU_MEM_SIZE:
                        diff = max_kvpr - max(compute_kvpr(g) for g in range(gpu_num) if g != gpu_id and g != other_gpu_id) - (other_model.req_rate / other_model.slo) / (GPU_MEM_SIZE - sum(m.model_size for m in placement[other_gpu_id]) - other_model.model_size)
                        if diff > 1e-9:
                            heapq.heappush(improvements, (-diff, gpu_id, other_gpu_id, other_model))
        # Re-evaluate global max KVPR after swap
        max_kvpr = max(compute_kvpr(i) for i in range(gpu_num))
        if max_kvpr >= max_kvpr:
            break

    return placement
